<header class="page-header"><div><h1><?= e(t('Work roles')) ?></h1><p class="muted"><?= e(t('Your responsibilities, work time and daily reflections across every role.')) ?></p></div><form method="post" action="/roles/templates"><?= csrf_field() ?><button class="secondary"><?= e(t('Add default roles')) ?></button></form></header>
<?php require ROOT.'/app/Core/views/notices.php'; ?>
<nav class="tabs"><a href="/roles?date=<?= e($date) ?>"><?= e(t('Today')) ?></a><a href="/roles?view=week&amp;date=<?= e($date) ?>"><?= e(t('Weekly review')) ?></a></nav>
<form class="inline" method="get" action="/roles"><label><?= e(t('Role')) ?><select name="role"><?php foreach($roles as $item): ?><option value="<?= e($item['id']) ?>" <?= $role&&$role['id']===$item['id']?'selected':'' ?>><?= e($item['name']) ?><?= $item['is_active']?'':' · '.e(t('Inactive')) ?></option><?php endforeach; ?></select></label><label><?= e(t('Date')) ?><input type="date" name="date" value="<?= e($date) ?>" required></label><input type="hidden" name="view" value="<?= e($view) ?>"><button class="secondary"><?= e(t('Show')) ?></button></form>
<?php if($running): ?><section class="card"><h2><?= e(t('Running timer')) ?> · <?= e($running['role_name']) ?></h2><p><?= e($running['task_title']??'') ?> <strong data-role-timer="<?= e(strtotime($running['started_at'])) ?>"></strong></p><form method="post" action="/roles/timer/stop" class="inline"><?= csrf_field() ?><label><?= e(t('End time (optional correction)')) ?><input type="datetime-local" name="ended_at"></label><button><?= e(t('Stop timer')) ?></button></form><p class="footnote"><?= e(t('One timer runs across all roles. A timer left running includes elapsed time until you stop or correct it.')) ?></p></section><?php endif; ?>
<?php if($view==='week'): ?>
<section class="card"><h2><?= e(t('Weekly review')) ?> · <?= e($start) ?> → <?= e($end) ?></h2><p class="muted"><?= e(t('Income estimates use the hourly rate saved when each timer started. They do not create money entries.')) ?></p>
<?php foreach($summary as $item): ?><article class="lesson-entry"><h3><?= e($item['name']) ?></h3><p><?= e(t('Recorded hours')) ?>: <?= e(number_format($item['seconds']/3600,2)) ?> · <?= e(t('Completed tasks')) ?>: <?= e($item['completed']) ?> · <?= e(t('Estimated income')) ?>: <?= money($item['estimated_income']) ?></p>
<?php if(module_enabled('Salary')): ?><details><summary><?= e(t('Record received income')) ?></summary><form method="post" action="/roles/income" class="form-grid"><?= csrf_field() ?><input type="hidden" name="role_id" value="<?= e($item['id']) ?>"><input type="hidden" name="start" value="<?= e($start) ?>"><input type="hidden" name="end" value="<?= e($end) ?>"><label><?= e(t('Received date')) ?><input name="date" type="date" value="<?= e(ui_date('Y-m-d')) ?>" required></label><label><?= e(t('Actual amount received in LKR')) ?><input name="amount" type="number" min="0.01" step="0.01" required></label><p class="footnote full"><?= e(t('Confirm only money you actually received. The same role and week cannot be posted twice.')) ?></p><button><?= e(t('Confirm received income')) ?></button></form></details><?php endif; ?></article><?php endforeach; ?></section>
<?php else: ?>
<?php if($role): ?>
<div class="two-col"><section class="card"><h2><?= e($role['name']) ?> · <?= e(t('Tasks')) ?></h2>
<?php if(!$tasks): ?><p class="muted"><?= e(t('No tasks for this role yet. Add a task or a recurring responsibility.')) ?></p><?php endif; ?>
<?php foreach($tasks as $task): ?><article class="task-row"><div><strong><?= e($task['title']) ?></strong><small><?= e($task['due_date']) ?> · <?= e(t(ucfirst($task['status']))) ?></small></div><form class="inline" method="post" action="/roles/tasks/<?= e($task['id']) ?>/status"><?= csrf_field() ?><input name="role_id" type="hidden" value="<?= e($role['id']) ?>"><select name="status" aria-label="<?= e(t('Task status')) ?>"><?php foreach(['open'=>t('Open'),'doing'=>t('In progress'),'blocked'=>t('Blocked'),'done'=>t('Done')]as $value=>$label): ?><option value="<?= e($value) ?>" <?= $value===$task['status']?'selected':'' ?>><?= e(t($label)) ?></option><?php endforeach; ?></select><button class="quiet"><?= e(t('Save')) ?></button></form></article><?php endforeach; ?>
<?php if($role['is_active']): ?><details><summary><?= e(t('Add task')) ?></summary><form class="stack" method="post" action="/roles/tasks"><?= csrf_field() ?><input name="role_id" type="hidden" value="<?= e($role['id']) ?>"><label><?= e(t('Title')) ?><input name="title" maxlength="200" required></label><label><?= e(t('Due date')) ?><input name="due_date" type="date" value="<?= e($date) ?>" required></label><label><?= e(t('Priority')) ?><select name="priority"><option value="1"><?= e(t('High')) ?></option><option value="2" selected><?= e(t('Normal')) ?></option><option value="3"><?= e(t('Low')) ?></option></select></label><button><?= e(t('Create task')) ?></button></form></details>
<?php if(!$running): ?><h3><?= e(t('Track time in this role')) ?></h3><form class="stack" method="post" action="/roles/timer/start"><?= csrf_field() ?><input name="role_id" type="hidden" value="<?= e($role['id']) ?>"><label><?= e(t('Task (optional)')) ?><select name="task_id"><option value=""><?= e(t('General role work')) ?></option><?php foreach($tasks as $task):if($task['status']==='done')continue; ?><option value="<?= e($task['id']) ?>"><?= e($task['title']) ?></option><?php endforeach; ?></select></label><label><?= e(t('Note (optional)')) ?><input name="note" maxlength="500"></label><button><?= e(t('Start timer')) ?></button></form><?php endif; ?><?php endif; ?></section>
<section class="card"><h2><?= e(t('Daily log')) ?></h2><form class="stack" method="post" action="/roles/daily"><?= csrf_field() ?><input name="role_id" type="hidden" value="<?= e($role['id']) ?>"><input name="date" type="hidden" value="<?= e($date) ?>"><?php foreach(['did'=>t('Did'),'blocked'=>t('Blocked'),'next'=>t('Next')]as $key=>$label): ?><label><?= e(t($label)) ?><textarea name="<?= e($key) ?>" maxlength="5000" rows="3"><?= e($daily[$key]??'') ?></textarea></label><?php endforeach; ?><button><?= e(t('Save daily log')) ?></button></form><?php if($daily&&module_enabled('Lessons')): ?><form method="post" action="/roles/daily/<?= e($daily['id']) ?>/lesson"><?= csrf_field() ?><button class="secondary"><?= e(t('Link reflection to Lessons')) ?></button></form><?php endif; ?></section></div>
<section class="card"><h2><?= e(t('Responsibilities')) ?></h2><p class="muted"><?= e(t('Today tasks are generated once per responsibility and period. Weekly tasks use the selected weekday; monthly tasks use the selected day or the last day of a shorter month.')) ?></p>
<?php $responsibilities=Db::all('SELECT * FROM role_responsibilities WHERE role_id=? ORDER BY id',[$role['id']]);$responsibilities[]=null;foreach($responsibilities as $responsibility): ?><details><summary><?= $responsibility?e($responsibility['title']):e(t('Add responsibility')) ?></summary><form class="form-grid" method="post" action="/roles/responsibilities"><?= csrf_field() ?><input type="hidden" name="role_id" value="<?= e($role['id']) ?>"><input type="hidden" name="id" value="<?= e($responsibility['id']??'') ?>"><label><?= e(t('Title')) ?><input name="title" value="<?= e($responsibility['title']??'') ?>" maxlength="200" required></label><label><?= e(t('Recurrence')) ?><select name="recurrence"><?php foreach(['daily'=>t('Daily'),'weekly'=>t('Weekly'),'monthly'=>t('Monthly')]as $key=>$label): ?><option value="<?= e($key) ?>" <?= ($responsibility['recurrence']??'daily')===$key?'selected':'' ?>><?= e(t($label)) ?></option><?php endforeach; ?></select></label><label><?= e(t('Estimate in minutes')) ?><input type="number" name="est_minutes" min="5" max="480" value="<?= e($responsibility['est_minutes']??30) ?>" required></label><label><?= e(t('Weekday (Monday = 1)')) ?><input name="week_day" type="number" min="1" max="7" value="<?= e($responsibility['week_day']??1) ?>" required></label><label><?= e(t('Day of month')) ?><input name="month_day" type="number" min="1" max="31" value="<?= e($responsibility['month_day']??1) ?>" required></label><label class="checkbox-label"><input type="checkbox" name="is_active" <?= !$responsibility||$responsibility['is_active']?'checked':'' ?>><?= e(t('Active')) ?></label><button><?= e(t('Save responsibility')) ?></button></form></details><?php endforeach; ?></section>
<section class="card"><h2><?= e(t('Recent time entries')) ?></h2><?php foreach(Db::all('SELECT * FROM role_time_logs WHERE role_id=? AND ended_at IS NOT NULL ORDER BY id DESC LIMIT 20',[$role['id']])as $entry): ?><details><summary><?= e($entry['started_at']) ?> → <?= e($entry['ended_at']) ?></summary><form method="post" action="/roles/time/<?= e($entry['id']) ?>/correct" class="form-grid"><?= csrf_field() ?><input type="hidden" name="role_id" value="<?= e($role['id']) ?>"><label><?= e(t('Start')) ?><input name="started_at" type="datetime-local" value="<?= e(str_replace(' ','T',$entry['started_at'])) ?>" required></label><label><?= e(t('End')) ?><input name="ended_at" type="datetime-local" value="<?= e(str_replace(' ','T',$entry['ended_at'])) ?>" required></label><label><?= e(t('Note')) ?><input name="note" maxlength="500" value="<?= e($entry['note']) ?>"></label><button><?= e(t('Save correction')) ?></button></form></details><?php endforeach; ?></section>
<?php endif; ?><?php endif; ?>
<details class="card"><summary><?= e(t('Manage roles')) ?></summary><?php $editingRoles=$roles;$editingRoles[]=null;foreach($editingRoles as $item): ?><form method="post" action="/roles/save" class="form-grid"><?= csrf_field() ?><input name="id" type="hidden" value="<?= e($item['id']??'') ?>"><label><?= e(t('Role name')) ?><input name="name" value="<?= e($item['name']??'') ?>" maxlength="200" required></label><label><?= e(t('Organization (optional)')) ?><input name="org" value="<?= e($item['org']??'') ?>" maxlength="200"></label><label><?= e(t('Colour')) ?><input name="color" type="color" value="<?= e($item['color']??'#0071e3') ?>"></label><label><?= e(t('Hourly rate in LKR')) ?><input name="hourly_rate" type="number" min="0" step="0.01" value="<?= e($item['hourly_rate']??0) ?>" required></label><label><?= e(t('Income source (optional)')) ?><input name="income_source" value="<?= e($item['income_source']??'') ?>" maxlength="200"></label><label class="checkbox-label"><input name="is_active" type="checkbox" <?= !$item||$item['is_active']?'checked':'' ?>><?= e(t('Active')) ?></label><button><?= e(t('Save role')) ?></button></form><?php endforeach; ?></details>
